def transform(grid):
    h, w = len(grid), len(grid[0])
    cross_r = next(r for r in range(h) if all(v == 3 for v in grid[r]))
    cross_c = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                distance = max(abs(r - cross_r), abs(c - cross_c))
                if distance % 2 == 0:
                    out[r][c] = 4
    return out
